def auto_calculate_spacing(lst_xaxis_var_names, lst_rotation, lst_xaxis_font_size, pd_data, base_h=0.03, base_v=0.15):
    """
    Smart spacing calculation - accounts for NEXT level's rotation.

    Key insight: spacing[i] makes room for level[i+1], not level[i]!
    """
    spacings = []
    n_levels = len(lst_xaxis_var_names)

    for i in range(n_levels):
        font_size = lst_xaxis_font_size[i] if i < len(lst_xaxis_font_size) else 10
        font_scale = font_size / 10.0

        # Check if NEXT level (i+1) has vertical rotation
        if i + 1 < n_levels and lst_rotation[i + 1].lower() == 'vertical':
            # Next level is vertical - need LOTS of space
            next_var = lst_xaxis_var_names[i + 1]
            unique_vals = pd_data[next_var].unique()
            max_len = max(len(str(v)) for v in unique_vals)

            # Vertical labels need space proportional to their length
            length_factor = 1.0 + max(0, (max_len - 10)) * 0.015
            spacing = base_v * font_scale * min(length_factor, 2.0)
        else:
            # Next level is horizontal or this is last level
            var_name = lst_xaxis_var_names[i]
            unique_vals = pd_data[var_name].unique()
            n_unique = len(unique_vals)

            # Horizontal: adjust for density
            density_factor = 1.0 + max(0, (n_unique - 2)) * 0.02  # Gentler scaling
            spacing = base_h * font_scale * min(density_factor, 1.5)

        spacings.append(round(spacing, 3))

    return spacings


